\label{ass:4.1}
There exists a neighborhood $\mathcal{N}\subset\mathbb{R}^{n}$ containing
the relevant iterates such that, for every $r=1,\ldots,N$,
 \ $F_r$ is twice continuously differentiable on $\mathcal{N}$ and its gradient is $L_F$-Lipschitz:
\begin{equation}\label{eq:gradient_lipschitz}
\|\nabla F_r(x)-\nabla F_r(y)\|_2 \leq L_F\|x-y\|_2, \qquad x,y\in\mathcal{N}. \end{equation}
Moreover, $h$ and $c$ are twice continuously differentiable on $\mathcal{N}$, and there exist finite constants $M_h,M_c>0$ such that
\[ \|\nabla^2 h_i(x)\|_2\leq M_h, \qquad i=1,\ldots,m, \]
and \[ \|\nabla^2 c_j(x)\|_2\leq M_c, \qquad j=1,\ldots,p, \] for all $x\in\mathcal{N}$.

\label{ass:4.2}
At every non-refresh iteration $k$, conditional on the filtration $\mathcal{F}_{k-1}$, the mini-batch
$\mathcal{B}_k\subseteq\{1,\ldots,N\}$ of cardinality
$|\mathcal{B}_k|=b_k$ is sampled independently and uniformly. Consequently, for every $x$ in the relevant neighborhood,
\begin{equation}\label{eq:unbiased_minibatch}
\mathbb{E}\left[\nabla F_{b_k}(x)\mid\mathcal{F}_{k-1}\right]=\nabla F(x), \end{equation}
When \(b_k=N\), the complete finite-sum index set \(\{1,\ldots,N\}\) is used.

\label{ass:4.3}
There exist constants $0<\underline b\leq\overline b<\infty$ and
$0<\underline g\leq\overline g<\infty$ such that, for all sufficiently
large $k$,
\begin{equation}\label{eq:BG_uniform_bounds}
\underline b I\preceq B^k\preceq\overline b I,\qquad \underline g I\preceq G^k\preceq\overline g I.\end{equation}
Thus, both local quadratic objective models remain uniformly
positive definite and bounded.

\label{ass:4.4}
The primal sequence $\{x^k\}$ generated by AVR-SS(QC)QP remains in a
compact subset $\mathcal{X}\subset\mathcal{N}$.

\label{lem:4.3}
Suppose Assumption~\ref{ass:4.1} holds. For every finite working penalty parameter \(\rho_k>0\), there exist \(\bar{\alpha}_k>0\) and \(C_\Phi^k>0\) such that, for every \(0<\alpha\leq\bar{\alpha}_k\),
\begin{equation}\label{eq:stochastic_merit_remainder}
\Phi(x^k+\alpha d^k;\rho_k)\leq\Phi(x^k;\rho_k)+\alpha D_k^\Phi+ \alpha\|e^k\|_2\|d^k\|_2+C_\Phi^k\alpha^2\|d^k\|_2^2,\end{equation} where $e^k=g^k-\nabla F(x^k),$ and one may take $C_\Phi^k=\frac{L_F}{2}+\frac{\rho_k}{2}\left(mM_h+pM_c\right).$

\label{lem:4.5}
Suppose the conditions of Lemma~\ref{lem:4.3} hold and \(D_k^\Phi<0\). Assume further that, for some constant $0\leq\vartheta<1-\sigma,$ the estimator error satisfies \[\|e^k\|_2\|d^k\|_2\leq\vartheta(-D_k^\Phi).\]
Then the Armijo backtracking procedure terminates after finitely many reductions.

\label{lem:4.6}
Suppose Assumptions~\ref{ass:4.1}--\ref{ass:4.5} hold. Then, on the regular tail associated with the accumulation set of \(\{x^k\}\), the local multiplier pairs generated by the effective SQP or SQCQP subproblems are uniformly bounded. Consequently, under the multiplier handoff
\[\lambda^{k+1}=\widehat{\lambda}^k,\qquad\mu^{k+1}=\widehat{\mu}^k,\]
there exist constants \(M_\lambda,M_\mu>0\) and a finite index \(K_\mu\) such that
\begin{equation}\label{eq:multiplier_boundedness}
\boxed{\|\lambda^k\|_\infty\leq M_\lambda,\qquad\|\mu^k\|_\infty\leq M_\mu,\qquad
k\geq K_\mu.}\end{equation}

\label{thm:4.1}
Suppose Assumptions~\ref{ass:4.1}--\ref{ass:4.5} hold and let the multiplier sequences satisfy the boundedness conclusion of Lemma~\ref{lem:4.6}. Assume additionally that, on the relevant regular tail of the iterates, the merit-descent penalty thresholds are uniformly bounded: there exist a finite constant
\(\rho_{\mathrm{des}}>0\) and an index \(K_{\mathrm{des}}\) such that, for every \(k\geq K_{\mathrm{des}}\), no within-iteration penalty increase is required whenever the working penalty satisfies \[\rho_k\geq\rho_{\mathrm{des}}.\]

Then the penalty sequence generated by the within-iteration merit-descent adjustment and the post-step update \[\rho_{k+1}=\begin{cases}\rho_k,&\rho_k\geq
\gamma_\rho\max\left\{1,\|\lambda^{k+1}\|_\infty,\|\mu^{k+1}\|_\infty\right\},\\[1mm]\gamma_\rho\rho_k,&\text{otherwise},\end{cases}\qquad \gamma_\rho>1,\]
is bounded above and can increase only finitely many times.
Consequently, there exist a finite index \(K_\rho\) and a finite constant \(\bar\rho>0\) such that
\begin{equation}\label{eq:penalty_stabilization}
\boxed{\rho_k=\bar\rho,\qquad k\geq K_\rho.}\end{equation}

\label{lem:4.7}
Suppose Assumptions~\ref{ass:4.1}--\ref{ass:4.5} hold and
\(\rho_k=\bar\rho\) for all sufficiently large \(k\). Define
\[\widehat M=\frac{\bar\rho}{\gamma_\rho},\qquad\rho_{\mathrm{gap}}=\bar\rho
\widehat M=\bar\rho\left(1-\frac1{\gamma_\rho}\right)>0,\] \[ and \qquad C_q=\frac12(mM_h+pM_c),\ C_H=\widehat M(mM_h+pM_c),\ \kappa_Q=\underline g-\frac12C_H-\bar\rho C_q>0.\]
Let $\kappa_\Phi=\min\{\underline b,\kappa_Q\}>0.$ Then, for every sufficiently large regular iteration, the effective direction \(d^k\) satisfies
\begin{equation}\label{eq:uniform_merit_descent}
D_k^\Phi\leq -\kappa_\Phi\|d^k\|_2^2-\rho_{\mathrm{gap}}V(x^k).
\end{equation}

\label{thm:4.2}
Suppose Assumptions~\ref{ass:4.1}--\ref{ass:4.5} hold, the conclusions of Theorem~\ref{thm:4.1} and Lemma~\ref{lem:4.7} hold, and the estimator-accuracy condition of Lemma~\ref{lem:4.5} is satisfied on the relevant tail so that the Armijo line search is well defined.

Then there exists a finite index \(K_L\) such that, for every
\(k\geq K_L\),
\begin{equation}\label{eq:coupled_lyapunov_descent}
\boxed{\mathbb E\left[\Psi^{k+1}\mid\mathcal F_k\right]\leq\Psi^k-a_1\alpha_k\|d^k\|_2^2-a_2E^k-a_3\alpha_kV(x^k),}
\end{equation}

where$ \ a_1=\frac{\sigma\kappa_\Phi}{2},\qquad a_2=\omega,\qquad a_3= \sigma\rho_{\mathrm{gap}}.$

\label{lem:4.9}
Suppose the conditions of Theorem~\ref{thm:4.2} hold. Then there exist a constant \(\underline{\alpha}>0\) and a finite index \(K_\alpha\) such that
\begin{equation}\label{eq:uniform_step_lower_bound}
\alpha_k\geq\underline{\alpha},\qquad k\geq K_\alpha.
\end{equation}

\label{lem:4.10}
Under the conditions of Theorem~\ref{thm:4.2},
\begin{equation}\label{eq:direction_and_feasibility_zero}
\|d^k\|_2\longrightarrow0,\qquad V(x^k)\longrightarrow0\qquad\text{a.s.}
\end{equation}
Consequently,
\[h(x^k)\longrightarrow0,\qquad c(x^k)^+\longrightarrow0\qquad\text{a.s.}\]

\label{lem:4.11}
Under Assumptions~\ref{ass:4.1}--\ref{ass:4.5} and the multiplier handoff rule,
$\mu^{k+1}=\widehat{\mu}^k,$ the outer inequality multipliers satisfy $\mu^k\geq0$ for every sufficiently large \(k\), and
\begin{equation}\label{eq:complementarity_residual_zero}
\|\mu^k\odot c(x^k)\|_2\longrightarrow0\qquad\text{a.s.}\end{equation}

\label{thm:4.3}
Suppose Assumptions~\ref{ass:4.1}--\ref{ass:4.5} hold together with the hypotheses of Theorem~\ref{thm:4.2}. Then the KKT residual of the outer AVR-SS(QC)QP sequence satisfies
\begin{equation}\label{eq:global_kkt_residual}
\left\|R_{\mathrm{KKT}}(x^k,\lambda^k,\mu^k)\right\|_2\longrightarrow0 \qquad\text{a.s.}\end{equation}
Consequently, every accumulation point $(x^\star,\lambda^\star,\mu^\star)$ of the primal--dual sequence satisfies
\[\nabla_x\mathcal L(x^\star,\lambda^\star,\mu^\star)=0,\]
\[h(x^\star)=0,\qquad c(x^\star)\leq0,\]
\[\mu^\star\geq0,\qquad\mu^\star\odot c(x^\star)=0\]
almost surely.

\label{lem:4.12}
Suppose Assumptions~\ref{ass:4.1}--\ref{ass:4.5} and the hypotheses of Theorem~\ref{thm:4.3} hold. Then
\begin{equation}\label{eq:vanishing_sqp_probe}
\|d_{\mathrm{SQP}}^k\|_2\longrightarrow0\qquad\text{a.s.}\end{equation}

\label{lem:4.13}
Under the conditions of Lemma~\ref{lem:4.12},
\begin{equation}\label{eq:vanishing_raw_rcmci}
\eta_k\longrightarrow0 \qquad\text{a.s.} \end{equation}
and\begin{equation}\label{eq:vanishing_smoothed_rcmci}
\bar{\eta}_k\longrightarrow0 \qquad\text{a.s.} \end{equation}

\label{thm:4.4}
Under the conditions of Theorem~\ref{thm:4.3} and Lemma~\ref{lem:4.12}, there exists a finite random index \(K_{\mathrm{switch}}\) such that
\begin{equation}\label{eq:eventual_sqp_selection}
\mathcal M_k=\mathrm{SQP},\qquad k\geq K_{\mathrm{switch}},\qquad \text{a.s.}
\end{equation}
Consequently, the effective direction passed to globalization is also the SQP direction for every sufficiently large iteration.

\label{cor:4.3}
For an infinite generated sequence, define
$N_{\mathrm{SQCQP}}(K)=\#\left\{0\leq k<K:\mathcal M_k=\mathrm{SQCQP}\right\}.$
Under the conditions of Theorem~\ref{thm:4.4},
\begin{equation}\label{eq:sqcqp_frequency_zero}
\lim_{K\to\infty}\frac{N_{\mathrm{SQCQP}}(K)}{K}=0 \qquad\text{a.s.}\end{equation}
